"use client";

import { useState, useEffect } from "react";
import { 
  Download, CheckSquare, ChevronLeft, RefreshCw, 
  Eye, Trash2, Filter, Plus, X, Search,
  Users, MapPin, Battery, Package, Tablet,
  BarChart, Clipboard, Share2, Mail, Cloud,
  CheckCircle, AlertCircle, Clock, Settings
} from "lucide-react";
import Link from "next/link";
import { useRouter } from "next/navigation";
import Layout from "@/components/Layout";
import { TabletDevice } from "@/types/tablet";

// Mock data
const mockTablets: TabletDevice[] = [
  // ... (same as your main tablets page)
];

export default function ExportSelected() {
  const router = useRouter();
  const [selectedTablets, setSelectedTablets] = useState<string[]>([]);
  const [searchQuery, setSearchQuery] = useState("");
  const [isExporting, setIsExporting] = useState(false);
  const [exportFormat, setExportFormat] = useState('csv');
  const [exportOptions, setExportOptions] = useState({
    includeDetails: true,
    includeHistory: false,
    compress: true,
    emailCopy: false,
    watermark: true,
  });
  const [bulkActions, setBulkActions] = useState<string[]>([]);
  const [showSelectionPanel, setShowSelectionPanel] = useState(false);

  // Load selected tablets from localStorage/session
  useEffect(() => {
    const saved = localStorage.getItem('selectedTablets');
    if (saved) {
      setSelectedTablets(JSON.parse(saved));
    }
  }, []);

  // Save selected tablets
  useEffect(() => {
    localStorage.setItem('selectedTablets', JSON.stringify(selectedTablets));
  }, [selectedTablets]);

  const filteredTablets = mockTablets.filter(tablet =>
    selectedTablets.includes(tablet.id) &&
    (searchQuery === "" ||
      tablet.deviceId.toLowerCase().includes(searchQuery.toLowerCase()) ||
      tablet.model.toLowerCase().includes(searchQuery.toLowerCase()) ||
      (tablet.assignedTo?.toLowerCase() || '').includes(searchQuery.toLowerCase()))
  );

  const handleSelectAll = () => {
    if (selectedTablets.length === mockTablets.length) {
      setSelectedTablets([]);
    } else {
      setSelectedTablets(mockTablets.map(t => t.id));
    }
  };

  const handleToggleSelect = (id: string) => {
    setSelectedTablets(prev =>
      prev.includes(id)
        ? prev.filter(tId => tId !== id)
        : [...prev, id]
    );
  };

  const handleBulkAction = (action: string) => {
    setBulkActions(prev => [...prev, action]);
    // Apply action to selected tablets
    alert(`Applying "${action}" to ${selectedTablets.length} tablets...`);
  };

  const handleExport = () => {
    if (selectedTablets.length === 0) {
      alert("Please select tablets to export");
      return;
    }

    setIsExporting(true);
    setTimeout(() => {
      setIsExporting(false);
      const filename = `selected-tablets-${new Date().toISOString().split('T')[0]}.${exportFormat}`;
      alert(`Exported ${selectedTablets.length} tablets to ${filename}`);
    }, 2000);
  };

  const handleShareExport = () => {
    const data = {
      tablets: selectedTablets,
      format: exportFormat,
      options: exportOptions,
      timestamp: new Date().toISOString(),
    };
    const encoded = btoa(JSON.stringify(data));
    const shareUrl = `${window.location.origin}/tablets/export/share?data=${encoded}`;
    
    navigator.clipboard.writeText(shareUrl);
    alert("Share link copied to clipboard!");
  };

  const bulkActionsList = [
    { id: 'assign', label: 'Assign to Team', icon: Users, color: 'bg-blue-100 text-blue-700' },
    { id: 'transfer', label: 'Transfer Location', icon: MapPin, color: 'bg-green-100 text-green-700' },
    { id: 'maintenance', label: 'Schedule Maintenance', icon: Settings, color: 'bg-yellow-100 text-yellow-700' },
    { id: 'update', label: 'Update Status', icon: RefreshCw, color: 'bg-purple-100 text-purple-700' },
    { id: 'export', label: 'Quick Export', icon: Download, color: 'bg-indigo-100 text-indigo-700' },
  ];

  const formatOptions = [
    { id: 'csv', label: 'CSV', description: 'For Excel analysis', icon: Clipboard },
    { id: 'excel', label: 'Excel', description: 'Native .xlsx format', icon: BarChart },
    { id: 'pdf', label: 'PDF', description: 'Formatted report', icon: FileText },
    { id: 'json', label: 'JSON', description: 'API/Developer use', icon: Code },
  ];

  return (
    <Layout>
      <div className="space-y-6">
        {/* Header */}
        <div className="flex flex-col lg:flex-row justify-between items-start lg:items-center gap-4">
          <div className="flex items-center space-x-4">
            <Link
              href="/tablets/export"
              className="p-2 hover:bg-gray-100 rounded-lg"
            >
              <ChevronLeft className="w-5 h-5" />
            </Link>
            <div>
              <h1 className="text-2xl font-bold text-gray-900">Export Selected Tablets</h1>
              <p className="text-gray-600">Select specific tablets for export and bulk actions</p>
            </div>
          </div>
          <div className="flex items-center space-x-3">
            <button
              onClick={() => router.refresh()}
              className="p-2 hover:bg-gray-100 rounded-lg"
            >
              <RefreshCw className="w-5 h-5" />
            </button>
            <Link
              href="/tablets"
              className="px-4 py-2 bg-gray-800 hover:bg-gray-900 text-white rounded-lg text-sm"
            >
              View All Tablets
            </Link>
          </div>
        </div>

        {/* Stats Bar */}
        <div className="bg-gradient-to-r from-blue-50 to-indigo-50 border border-blue-200 rounded-xl p-6">
          <div className="flex flex-col lg:flex-row items-center justify-between gap-6">
            <div className="flex items-center space-x-6">
              <div className="text-center">
                <div className="text-3xl font-bold text-gray-900">{selectedTablets.length}</div>
                <div className="text-sm text-gray-600">Selected</div>
              </div>
              <div className="h-12 w-px bg-blue-200"></div>
              <div className="text-center">
                <div className="text-3xl font-bold text-gray-900">{mockTablets.length}</div>
                <div className="text-sm text-gray-600">Total Available</div>
              </div>
              <div className="h-12 w-px bg-blue-200"></div>
              <div className="text-center">
                <div className="text-3xl font-bold text-gray-900">
                  {selectedTablets.length > 0 ? 
                    `${Math.round((selectedTablets.length / mockTablets.length) * 100)}%` : 
                    '0%'
                  }
                </div>
                <div className="text-sm text-gray-600">Of Inventory</div>
              </div>
            </div>
            <div className="flex items-center space-x-3">
              <button
                onClick={handleSelectAll}
                className={`px-4 py-2 rounded-lg font-medium ${
                  selectedTablets.length === mockTablets.length
                    ? 'bg-red-100 text-red-700 hover:bg-red-200'
                    : 'bg-blue-100 text-blue-700 hover:bg-blue-200'
                }`}
              >
                {selectedTablets.length === mockTablets.length ? 'Deselect All' : 'Select All'}
              </button>
              <button
                onClick={() => setSelectedTablets([])}
                className="px-4 py-2 bg-gray-100 text-gray-700 rounded-lg hover:bg-gray-200 font-medium"
              >
                Clear Selection
              </button>
            </div>
          </div>
        </div>

        <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
          {/* Left Column - Selection Panel */}
          <div className="lg:col-span-2 space-y-6">
            {/* Search and Filter */}
            <div className="bg-white rounded-xl border border-gray-200 p-6">
              <div className="flex flex-col md:flex-row gap-4">
                <div className="flex-1">
                  <div className="relative">
                    <Search className="absolute left-3 top-1/2 transform -translate-y-1/2 h-5 w-5 text-gray-400" />
                    <input
                      type="search"
                      placeholder="Search selected tablets..."
                      value={searchQuery}
                      onChange={(e) => setSearchQuery(e.target.value)}
                      className="pl-10 pr-4 py-3 w-full border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-transparent"
                    />
                  </div>
                </div>
                <button
                  onClick={() => setShowSelectionPanel(!showSelectionPanel)}
                  className="px-4 py-3 border border-gray-300 rounded-lg hover:bg-gray-50 flex items-center justify-center"
                >
                  <Plus className="w-5 h-5 mr-2" />
                  Add More
                </button>
              </div>
            </div>

            {/* Selected Tablets List */}
            <div className="bg-white rounded-xl border border-gray-200 overflow-hidden">
              <div className="p-6 border-b border-gray-200">
                <div className="flex items-center justify-between">
                  <h3 className="font-medium text-gray-900">Selected Tablets</h3>
                  <span className="text-sm text-gray-600">
                    {filteredTablets.length} items
                  </span>
                </div>
              </div>
              
              <div className="divide-y divide-gray-200 max-h-[500px] overflow-y-auto">
                {filteredTablets.length === 0 ? (
                  <div className="p-12 text-center">
                    <CheckSquare className="w-12 h-12 text-gray-300 mx-auto mb-4" />
                    <h4 className="text-lg font-medium text-gray-900 mb-2">No tablets selected</h4>
                    <p className="text-gray-600 mb-6">Select tablets from the inventory to export</p>
                    <Link
                      href="/tablets"
                      className="inline-flex items-center px-4 py-2 bg-blue-600 text-white rounded-lg hover:bg-blue-700"
                    >
                      <Plus className="w-5 h-5 mr-2" />
                      Browse Tablets
                    </Link>
                  </div>
                ) : (
                  filteredTablets.map((tablet) => (
                    <div
                      key={tablet.id}
                      className="p-4 hover:bg-gray-50 flex items-center"
                    >
                      <input
                        type="checkbox"
                        checked={selectedTablets.includes(tablet.id)}
                        onChange={() => handleToggleSelect(tablet.id)}
                        className="h-4 w-4 text-blue-600 rounded border-gray-300 focus:ring-blue-500"
                      />
                      
                      <div className="ml-4 flex-1">
                        <div className="flex items-center justify-between">
                          <div>
                            <div className="font-medium text-gray-900">{tablet.deviceId}</div>
                            <div className="text-sm text-gray-600">{tablet.model}</div>
                          </div>
                          <div className="flex items-center space-x-4">
                            <span className={`px-2 py-1 rounded text-xs font-medium ${
                              tablet.status === 'available' ? 'bg-green-100 text-green-800' :
                              tablet.status === 'issued' ? 'bg-blue-100 text-blue-800' :
                              tablet.status === 'damaged' ? 'bg-red-100 text-red-800' :
                              tablet.status === 'missing' ? 'bg-orange-100 text-orange-800' :
                              'bg-yellow-100 text-yellow-800'
                            }`}>
                              {tablet.status}
                            </span>
                            <span className="text-sm text-gray-600">{tablet.battery}%</span>
                          </div>
                        </div>
                        
                        <div className="grid grid-cols-2 md:grid-cols-4 gap-4 mt-3 text-sm">
                          <div className="flex items-center">
                            <Users className="w-4 h-4 text-gray-400 mr-2" />
                            <span className="text-gray-600">
                              {tablet.assignedTo || 'Unassigned'}
                            </span>
                          </div>
                          <div className="flex items-center">
                            <MapPin className="w-4 h-4 text-gray-400 mr-2" />
                            <span className="text-gray-600">{tablet.location}</span>
                          </div>
                          <div className="flex items-center">
                            <Package className="w-4 h-4 text-gray-400 mr-2" />
                            <span className="text-gray-600 capitalize">{tablet.condition}</span>
                          </div>
                          <div className="flex items-center">
                            <Battery className="w-4 h-4 text-gray-400 mr-2" />
                            <span className={`font-medium ${
                              tablet.battery > 70 ? 'text-green-600' :
                              tablet.battery > 30 ? 'text-yellow-600' :
                              'text-red-600'
                            }`}>
                              {tablet.battery}%
                            </span>
                          </div>
                        </div>
                      </div>
                      
                      <button
                        onClick={() => handleToggleSelect(tablet.id)}
                        className="ml-4 p-2 text-gray-400 hover:text-red-600 hover:bg-red-50 rounded-lg"
                      >
                        <X className="w-5 h-5" />
                      </button>
                    </div>
                  ))
                )}
              </div>
            </div>

            {/* Bulk Actions */}
            {selectedTablets.length > 0 && (
              <div className="bg-white rounded-xl border border-gray-200 p-6">
                <h3 className="font-medium text-gray-900 mb-4">Bulk Actions</h3>
                <div className="grid grid-cols-2 md:grid-cols-5 gap-3">
                  {bulkActionsList.map((action) => (
                    <button
                      key={action.id}
                      onClick={() => handleBulkAction(action.label)}
                      className={`p-3 rounded-lg flex flex-col items-center justify-center ${action.color} hover:opacity-90 transition-opacity`}
                    >
                      <action.icon className="w-5 h-5 mb-2" />
                      <span className="text-xs font-medium text-center">{action.label}</span>
                    </button>
                  ))}
                </div>
              </div>
            )}
          </div>

          {/* Right Column - Export Configuration */}
          <div className="space-y-6">
            {/* Export Configuration */}
            <div className="bg-white rounded-xl border border-gray-200 p-6">
              <h2 className="text-lg font-bold text-gray-900 mb-4">Export Configuration</h2>
              
              <div className="space-y-4">
                <div>
                  <label className="block text-sm font-medium text-gray-700 mb-2">
                    Export Format
                  </label>
                  <div className="grid grid-cols-2 gap-2">
                    {formatOptions.map((format) => (
                      <button
                        key={format.id}
                        onClick={() => setExportFormat(format.id)}
                        className={`p-3 rounded-lg border ${
                          exportFormat === format.id
                            ? 'border-blue-500 bg-blue-50'
                            : 'border-gray-200 hover:border-gray-300'
                        }`}
                      >
                        <div className="text-center">
                          <div className="font-medium text-gray-900">{format.label}</div>
                          <div className="text-xs text-gray-500 mt-1">{format.description}</div>
                        </div>
                      </button>
                    ))}
                  </div>
                </div>

                <div>
                  <label className="block text-sm font-medium text-gray-700 mb-2">
                    Export Options
                  </label>
                  <div className="space-y-3">
                    {Object.entries(exportOptions).map(([key, value]) => (
                      <label
                        key={key}
                        className="flex items-center justify-between p-3 border border-gray-200 rounded-lg hover:bg-gray-50 cursor-pointer"
                      >
                        <div className="flex items-center">
                          <input
                            type="checkbox"
                            checked={value}
                            onChange={(e) => setExportOptions(prev => ({
                              ...prev,
                              [key]: e.target.checked
                            }))}
                            className="rounded border-gray-300 text-blue-600 focus:ring-blue-500 h-4 w-4"
                          />
                          <span className="ml-3 text-sm text-gray-700 capitalize">
                            {key.replace(/([A-Z])/g, ' $1').trim()}
                          </span>
                        </div>
                        <span className="text-xs text-gray-500">
                          {key === 'includeDetails' && 'Full details'}
                          {key === 'includeHistory' && 'With history'}
                          {key === 'compress' && 'ZIP file'}
                          {key === 'emailCopy' && 'Send email'}
                          {key === 'watermark' && 'Add watermark'}
                        </span>
                      </label>
                    ))}
                  </div>
                </div>

                <div className="pt-4 border-t border-gray-200">
                  <div className="space-y-2 text-sm">
                    <div className="flex justify-between">
                      <span className="text-gray-600">Selected Tablets:</span>
                      <span className="font-medium">{selectedTablets.length}</span>
                    </div>
                    <div className="flex justify-between">
                      <span className="text-gray-600">Estimated Size:</span>
                      <span className="font-medium">
                        {(selectedTablets.length * 0.05).toFixed(1)} MB
                      </span>
                    </div>
                    <div className="flex justify-between">
                      <span className="text-gray-600">Export Format:</span>
                      <span className="font-medium">{exportFormat.toUpperCase()}</span>
                    </div>
                  </div>
                </div>
              </div>
            </div>

            {/* Export Actions */}
            <div className="bg-white rounded-xl border border-gray-200 p-6">
              <h2 className="text-lg font-bold text-gray-900 mb-4">Export Actions</h2>
              
              <div className="space-y-3">
                <button
                  onClick={handleExport}
                  disabled={isExporting || selectedTablets.length === 0}
                  className="w-full py-3 bg-gradient-to-r from-blue-600 to-indigo-600 hover:from-blue-700 hover:to-indigo-700 text-white font-medium rounded-lg flex items-center justify-center disabled:opacity-50"
                >
                  {isExporting ? (
                    <>
                      <RefreshCw className="w-5 h-5 mr-2 animate-spin" />
                      Exporting...
                    </>
                  ) : (
                    <>
                      <Download className="w-5 h-5 mr-2" />
                      Export Selected
                    </>
                  )}
                </button>
                
                <button
                  onClick={handleShareExport}
                  disabled={selectedTablets.length === 0}
                  className="w-full py-3 border border-gray-300 text-gray-700 font-medium rounded-lg hover:bg-gray-50 flex items-center justify-center disabled:opacity-50"
                >
                  <Share2 className="w-5 h-5 mr-2" />
                  Share Export Link
                </button>
                
                <button
                  onClick={() => {
                    if (selectedTablets.length > 0 && exportOptions.emailCopy) {
                      alert(`Scheduled export of ${selectedTablets.length} tablets`);
                    }
                  }}
                  className="w-full py-3 border border-gray-300 text-gray-700 font-medium rounded-lg hover:bg-gray-50 flex items-center justify-center"
                >
                  <Clock className="w-5 h-5 mr-2" />
                  Schedule Export
                </button>
                
                <button
                  onClick={() => {
                    // Save selection as template
                    localStorage.setItem('exportSelectionTemplate', JSON.stringify({
                      tablets: selectedTablets,
                      options: exportOptions,
                      format: exportFormat,
                    }));
                    alert('Selection saved as template!');
                  }}
                  className="w-full py-3 border border-gray-300 text-gray-700 font-medium rounded-lg hover:bg-gray-50 flex items-center justify-center"
                >
                  <Cloud className="w-5 h-5 mr-2" />
                  Save Selection
                </button>
              </div>
              
              {selectedTablets.length === 0 && (
                <div className="mt-4 p-3 bg-yellow-50 border border-yellow-200 rounded-lg">
                  <div className="flex items-center">
                    <AlertCircle className="w-5 h-5 text-yellow-600 mr-2" />
                    <span className="text-sm text-yellow-700">
                      Select tablets to enable export options
                    </span>
                  </div>
                </div>
              )}
            </div>

            {/* Quick Stats */}
            <div className="bg-blue-50 border border-blue-200 rounded-xl p-6">
              <h3 className="font-medium text-gray-900 mb-4 flex items-center">
                <BarChart className="w-5 h-5 mr-2" />
                Selection Stats
              </h3>
              <div className="space-y-3">
                {selectedTablets.length > 0 ? (
                  <>
                    <div className="flex justify-between text-sm">
                      <span className="text-gray-600">By Status:</span>
                      <div className="space-x-2">
                        {['available', 'issued', 'damaged', 'missing', 'maintenance'].map(status => {
                          const count = filteredTablets.filter(t => t.status === status).length;
                          return count > 0 ? (
                            <span key={status} className="text-xs font-medium">
                              {count} {status.charAt(0)}
                            </span>
                          ) : null;
                        })}
                      </div>
                    </div>
                    <div className="flex justify-between text-sm">
                      <span className="text-gray-600">Avg Battery:</span>
                      <span className="font-medium">
                        {Math.round(filteredTablets.reduce((acc, t) => acc + t.battery, 0) / filteredTablets.length)}%
                      </span>
                    </div>
                    <div className="flex justify-between text-sm">
                      <span className="text-gray-600">Locations:</span>
                      <span className="font-medium">
                        {new Set(filteredTablets.map(t => t.location)).size}
                      </span>
                    </div>
                    <div className="flex justify-between text-sm">
                      <span className="text-gray-600">Models:</span>
                      <span className="font-medium">
                        {new Set(filteredTablets.map(t => t.model)).size}
                      </span>
                    </div>
                  </>
                ) : (
                  <div className="text-center py-4">
                    <CheckSquare className="w-8 h-8 text-gray-300 mx-auto mb-2" />
                    <p className="text-sm text-gray-600">Select tablets to see stats</p>
                  </div>
                )}
              </div>
            </div>
          </div>
        </div>

        {/* Selection Panel Modal */}
        {showSelectionPanel && (
          <div className="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center z-50 p-4">
            <div className="bg-white rounded-xl w-full max-w-4xl max-h-[90vh] overflow-hidden">
              <div className="p-6 border-b border-gray-200 flex items-center justify-between">
                <h3 className="text-lg font-bold text-gray-900">Add Tablets to Selection</h3>
                <button
                  onClick={() => setShowSelectionPanel(false)}
                  className="p-2 hover:bg-gray-100 rounded-lg"
                >
                  <X className="w-5 h-5" />
                </button>
              </div>
              
              <div className="p-6 max-h-[60vh] overflow-y-auto">
                <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
                  {mockTablets.filter(t => !selectedTablets.includes(t.id)).slice(0, 12).map(tablet => (
                    <div
                      key={tablet.id}
                      className="p-4 border border-gray-200 rounded-lg hover:border-blue-300 hover:bg-blue-50 cursor-pointer"
                      onClick={() => handleToggleSelect(tablet.id)}
                    >
                      <div className="flex items-center justify-between mb-2">
                        <div className="font-medium text-gray-900">{tablet.deviceId}</div>
                        <Plus className="w-4 h-4 text-gray-400" />
                      </div>
                      <div className="text-sm text-gray-600">{tablet.model}</div>
                      <div className="flex items-center justify-between mt-3">
                        <span className={`px-2 py-1 rounded text-xs ${
                          tablet.status === 'available' ? 'bg-green-100 text-green-800' :
                          'bg-blue-100 text-blue-800'
                        }`}>
                          {tablet.status}
                        </span>
                        <span className="text-sm font-medium">{tablet.battery}%</span>
                      </div>
                    </div>
                  ))}
                </div>
              </div>
              
              <div className="p-6 border-t border-gray-200 flex justify-end">
                <button
                  onClick={() => setShowSelectionPanel(false)}
                  className="px-6 py-2 bg-blue-600 text-white rounded-lg hover:bg-blue-700"
                >
                  Done
                </button>
              </div>
            </div>
          </div>
        )}
      </div>
    </Layout>
  );
}

"use client";

import { useState } from "react";
import { 
  Plus, ChevronLeft, Camera, Barcode, 
  Save, X, Upload, RefreshCw, CheckCircle,
  AlertCircle, Tablet, Battery, HardDrive,
  Cpu, MemoryStick, MapPin, Calendar, Shield,
  QrCode, Scan, Package, User, Settings,
  Info, Clipboard
} from "lucide-react";
import Link from "next/link";
import { useRouter } from "next/navigation";
import Layout from "@/components/Layout";

interface NewTabletForm {
  deviceId: string;
  serialNumber: string;
  imei: string;
  model: string;
  status: string;
  condition: string;
  battery: number;
  storage: string;
  ram: string;
  os: string;
  location: string;
  purchaseDate: string;
  warranty: string;
  assignedTo: string;
  assignedActivity: string;
  department: string;
  notes: string;
}

const modelOptions = [
  "Samsung Galaxy Tab A8",
  "Samsung Galaxy Tab S6 Lite",
  "Samsung Galaxy Tab S7 FE",
  "Samsung Galaxy Tab S9",
  "Lenovo Tab M10",
  "Lenovo Tab P11",
  "Lenovo Tab M8",
  "iPad 9th Gen",
  "iPad Air 5",
  "Other"
];

const statusOptions = [
  { value: "available", label: "Available", color: "bg-green-100 text-green-800" },
  { value: "issued", label: "Issued", color: "bg-blue-100 text-blue-800" },
  { value: "damaged", label: "Damaged", color: "bg-red-100 text-red-800" },
  { value: "missing", label: "Missing", color: "bg-orange-100 text-orange-800" },
  { value: "maintenance", label: "Maintenance", color: "bg-yellow-100 text-yellow-800" },
];

const conditionOptions = [
  { value: "excellent", label: "Excellent", color: "bg-green-100 text-green-800" },
  { value: "good", label: "Good", color: "bg-blue-100 text-blue-800" },
  { value: "fair", label: "Fair", color: "bg-yellow-100 text-yellow-800" },
  { value: "poor", label: "Poor", color: "bg-red-100 text-red-800" },
];

const storageOptions = ["32GB", "64GB", "128GB", "256GB", "512GB", "1TB"];
const ramOptions = ["2GB", "3GB", "4GB", "6GB", "8GB", "12GB", "16GB"];
const osOptions = ["Android 11", "Android 12", "Android 13", "Android 14", "iOS 15", "iOS 16", "iOS 17"];

export default function NewTabletPage() {
  const router = useRouter();
  const [form, setForm] = useState<NewTabletForm>({
    deviceId: "",
    serialNumber: "",
    imei: "",
    model: "",
    status: "available",
    condition: "good",
    battery: 100,
    storage: "128GB",
    ram: "4GB",
    os: "Android 13",
    location: "Nairobi Warehouse",
    purchaseDate: new Date().toISOString().split('T')[0],
    warranty: new Date(new Date().setFullYear(new Date().getFullYear() + 2)).toISOString().split('T')[0],
    assignedTo: "",
    assignedActivity: "",
    department: "IT",
    notes: "",
  });
  
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [errors, setErrors] = useState<Record<string, string>>({});
  const [activeTab, setActiveTab] = useState('basic');
  const [showScanner, setShowScanner] = useState(false);

  const generateDeviceId = () => {
    const prefix = "KNBS-TAB-";
    const random = Math.floor(Math.random() * 900) + 100;
    const newId = `${prefix}${random.toString().padStart(3, '0')}`;
    setForm(prev => ({ ...prev, deviceId: newId }));
  };

  const validateForm = () => {
    const newErrors: Record<string, string> = {};
    
    if (!form.deviceId.trim()) newErrors.deviceId = "Device ID is required";
    if (!form.serialNumber.trim()) newErrors.serialNumber = "Serial number is required";
    if (!form.imei.trim()) newErrors.imei = "IMEI is required";
    if (!form.model) newErrors.model = "Model is required";
    if (form.battery < 0 || form.battery > 100) newErrors.battery = "Battery must be between 0-100%";
    
    setErrors(newErrors);
    return Object.keys(newErrors).length === 0;
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    
    if (!validateForm()) {
      return;
    }
    
    setIsSubmitting(true);
    
    // Simulate API call
    setTimeout(() => {
      setIsSubmitting(false);
      alert(`Tablet ${form.deviceId} added successfully!`);
      router.push('/tablets');
    }, 2000);
  };

  const handleScan = (type: 'barcode' | 'qr') => {
    setShowScanner(true);
    // In real app, this would open scanner
    setTimeout(() => {
      setShowScanner(false);
      // Simulate scan results
      if (type === 'barcode') {
        setForm(prev => ({
          ...prev,
          serialNumber: `SN${Math.floor(Math.random() * 1000000).toString().padStart(6, '0')}`,
          imei: `${Math.floor(Math.random() * 1000000000000000).toString().padStart(15, '0')}`
        }));
      }
    }, 1500);
  };

  const tabs = [
    { id: 'basic', label: 'Basic Info', icon: Info },
    { id: 'specs', label: 'Specifications', icon: Cpu },
    { id: 'assignment', label: 'Assignment', icon: User },
    { id: 'additional', label: 'Additional', icon: Settings },
  ];

  return (
    <Layout>
      <div className="space-y-6">
        {/* Header */}
        <div className="flex flex-col lg:flex-row justify-between items-start lg:items-center gap-4">
          <div className="flex items-center space-x-4">
            <Link
              href="/tablets"
              className="p-2 hover:bg-gray-100 rounded-lg"
            >
              <ChevronLeft className="w-5 h-5" />
            </Link>
            <div>
              <h1 className="text-2xl font-bold text-gray-900">Add New Tablet</h1>
              <p className="text-gray-600">Register a new tablet in the inventory system</p>
            </div>
          </div>
          <div className="flex items-center space-x-3">
            <button
              onClick={generateDeviceId}
              className="px-4 py-2 border border-gray-300 rounded-lg hover:bg-gray-50 text-sm flex items-center"
            >
              <RefreshCw className="w-4 h-4 mr-2" />
              Generate ID
            </button>
            <button
              type="submit"
              form="new-tablet-form"
              disabled={isSubmitting}
              className="px-4 py-2 bg-blue-600 hover:bg-blue-700 text-white rounded-lg text-sm flex items-center disabled:opacity-50"
            >
              <Save className="w-4 h-4 mr-2" />
              {isSubmitting ? 'Saving...' : 'Save Tablet'}
            </button>
          </div>
        </div>

        <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
          {/* Left Column - Form */}
          <div className="lg:col-span-2">
            <form id="new-tablet-form" onSubmit={handleSubmit} className="space-y-6">
              {/* Tabs */}
              <div className="bg-white rounded-xl border border-gray-200 overflow-hidden">
                <div className="border-b border-gray-200">
                  <nav className="flex overflow-x-auto">
                    {tabs.map(tab => (
                      <button
                        key={tab.id}
                        type="button"
                        onClick={() => setActiveTab(tab.id)}
                        className={`px-6 py-3 font-medium text-sm flex items-center border-b-2 transition-colors whitespace-nowrap ${
                          activeTab === tab.id
                            ? 'border-blue-500 text-blue-600'
                            : 'border-transparent text-gray-600 hover:text-gray-900'
                        }`}
                      >
                        <tab.icon className="w-4 h-4 mr-2" />
                        {tab.label}
                      </button>
                    ))}
                  </nav>
                </div>
                
                <div className="p-6">
                  {/* Basic Info Tab */}
                  {activeTab === 'basic' && (
                    <div className="space-y-6">
                      <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                        <div>
                          <label className="block text-sm font-medium text-gray-700 mb-2">
                            Device ID *
                          </label>
                          <div className="flex space-x-2">
                            <input
                              type="text"
                              value={form.deviceId}
                              onChange={(e) => setForm(prev => ({ ...prev, deviceId: e.target.value }))}
                              className={`flex-1 px-3 py-2 border ${errors.deviceId ? 'border-red-300' : 'border-gray-300'} rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-blue-500`}
                              placeholder="KNBS-TAB-001"
                            />
                            <button
                              type="button"
                              onClick={generateDeviceId}
                              className="px-3 py-2 border border-gray-300 rounded-lg hover:bg-gray-50"
                              title="Generate ID"
                            >
                              <RefreshCw className="w-4 h-4" />
                            </button>
                          </div>
                          {errors.deviceId && (
                            <p className="mt-1 text-sm text-red-600">{errors.deviceId}</p>
                          )}
                        </div>
                        
                        <div>
                          <label className="block text-sm font-medium text-gray-700 mb-2">
                            Model *
                          </label>
                          <select
                            value={form.model}
                            onChange={(e) => setForm(prev => ({ ...prev, model: e.target.value }))}
                            className={`w-full px-3 py-2 border ${errors.model ? 'border-red-300' : 'border-gray-300'} rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-blue-500`}
                          >
                            <option value="">Select a model</option>
                            {modelOptions.map(model => (
                              <option key={model} value={model}>{model}</option>
                            ))}
                          </select>
                          {errors.model && (
                            <p className="mt-1 text-sm text-red-600">{errors.model}</p>
                          )}
                        </div>
                      </div>
                      
                      <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                        <div>
                          <label className="block text-sm font-medium text-gray-700 mb-2">
                            Serial Number *
                          </label>
                          <div className="flex space-x-2">
                            <input
                              type="text"
                              value={form.serialNumber}
                              onChange={(e) => setForm(prev => ({ ...prev, serialNumber: e.target.value }))}
                              className={`flex-1 px-3 py-2 border ${errors.serialNumber ? 'border-red-300' : 'border-gray-300'} rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-blue-500`}
                              placeholder="Enter serial number"
                            />
                            <button
                              type="button"
                              onClick={() => handleScan('barcode')}
                              className="px-3 py-2 border border-gray-300 rounded-lg hover:bg-gray-50"
                              title="Scan Barcode"
                            >
                              <Barcode className="w-4 h-4" />
                            </button>
                          </div>
                          {errors.serialNumber && (
                            <p className="mt-1 text-sm text-red-600">{errors.serialNumber}</p>
                          )}
                        </div>
                        
                        <div>
                          <label className="block text-sm font-medium text-gray-700 mb-2">
                            IMEI Number *
                          </label>
                          <div className="flex space-x-2">
                            <input
                              type="text"
                              value={form.imei}
                              onChange={(e) => setForm(prev => ({ ...prev, imei: e.target.value }))}
                              className={`flex-1 px-3 py-2 border ${errors.imei ? 'border-red-300' : 'border-gray-300'} rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-blue-500`}
                              placeholder="15-digit IMEI"
                              maxLength={15}
                            />
                            <button
                              type="button"
                              onClick={() => handleScan('qr')}
                              className="px-3 py-2 border border-gray-300 rounded-lg hover:bg-gray-50"
                              title="Scan QR Code"
                            >
                              <QrCode className="w-4 h-4" />
                            </button>
                          </div>
                          {errors.imei && (
                            <p className="mt-1 text-sm text-red-600">{errors.imei}</p>
                          )}
                        </div>
                      </div>
                      
                      <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                        <div>
                          <label className="block text-sm font-medium text-gray-700 mb-2">
                            Status
                          </label>
                          <div className="grid grid-cols-2 md:grid-cols-3 gap-2">
                            {statusOptions.map(option => (
                              <label
                                key={option.value}
                                className={`p-3 border rounded-lg cursor-pointer flex items-center justify-center ${
                                  form.status === option.value
                                    ? `${option.color} border-transparent`
                                    : 'border-gray-200 hover:border-gray-300'
                                }`}
                              >
                                <input
                                  type="radio"
                                  name="status"
                                  value={option.value}
                                  checked={form.status === option.value}
                                  onChange={(e) => setForm(prev => ({ ...prev, status: e.target.value }))}
                                  className="sr-only"
                                />
                                <span className="text-sm font-medium">{option.label}</span>
                              </label>
                            ))}
                          </div>
                        </div>
                        
                        <div>
                          <label className="block text-sm font-medium text-gray-700 mb-2">
                            Condition
                          </label>
                          <div className="grid grid-cols-2 md:grid-cols-2 gap-2">
                            {conditionOptions.map(option => (
                              <label
                                key={option.value}
                                className={`p-3 border rounded-lg cursor-pointer flex items-center justify-center ${
                                  form.condition === option.value
                                    ? `${option.color} border-transparent`
                                    : 'border-gray-200 hover:border-gray-300'
                                }`}
                              >
                                <input
                                  type="radio"
                                  name="condition"
                                  value={option.value}
                                  checked={form.condition === option.value}
                                  onChange={(e) => setForm(prev => ({ ...prev, condition: e.target.value }))}
                                  className="sr-only"
                                />
                                <span className="text-sm font-medium">{option.label}</span>
                              </label>
                            ))}
                          </div>
                        </div>
                      </div>
                      
                      <div>
                        <label className="block text-sm font-medium text-gray-700 mb-2">
                          Battery Level
                        </label>
                        <div className="space-y-4">
                          <div className="flex items-center justify-between">
                            <span className="text-sm text-gray-600">{form.battery}%</span>
                            <div className="flex items-center space-x-2">
                              <button
                                type="button"
                                onClick={() => setForm(prev => ({ ...prev, battery: Math.max(0, prev.battery - 10) }))}
                                className="p-1"
                              >
                                -
                              </button>
                              <button
                                type="button"
                                onClick={() => setForm(prev => ({ ...prev, battery: Math.min(100, prev.battery + 10) }))}
                                className="p-1"
                              >
                                +
                              </button>
                            </div>
                          </div>
                          <input
                            type="range"
                            min="0"
                            max="100"
                            value={form.battery}
                            onChange={(e) => setForm(prev => ({ ...prev, battery: parseInt(e.target.value) }))}
                            className="w-full h-2 bg-gray-200 rounded-lg appearance-none cursor-pointer"
                          />
                          {errors.battery && (
                            <p className="mt-1 text-sm text-red-600">{errors.battery}</p>
                          )}
                        </div>
                      </div>
                    </div>
                  )}

                  {/* Specifications Tab */}
                  {activeTab === 'specs' && (
                    <div className="space-y-6">
                      <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                        <div>
                          <label className="block text-sm font-medium text-gray-700 mb-2">
                            Storage Capacity
                          </label>
                          <select
                            value={form.storage}
                            onChange={(e) => setForm(prev => ({ ...prev, storage: e.target.value }))}
                            className="w-full px-3 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-blue-500"
                          >
                            {storageOptions.map(size => (
                              <option key={size} value={size}>{size}</option>
                            ))}
                          </select>
                        </div>
                        
                        <div>
                          <label className="block text-sm font-medium text-gray-700 mb-2">
                            RAM
                          </label>
                          <select
                            value={form.ram}
                            onChange={(e) => setForm(prev => ({ ...prev, ram: e.target.value }))}
                            className="w-full px-3 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-blue-500"
                          >
                            {ramOptions.map(ram => (
                              <option key={ram} value={ram}>{ram}</option>
                            ))}
                          </select>
                        </div>
                      </div>
                      
                      <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                        <div>
                          <label className="block text-sm font-medium text-gray-700 mb-2">
                            Operating System
                          </label>
                          <select
                            value={form.os}
                            onChange={(e) => setForm(prev => ({ ...prev, os: e.target.value }))}
                            className="w-full px-3 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-blue-500"
                          >
                            {osOptions.map(os => (
                              <option key={os} value={os}>{os}</option>
                            ))}
                          </select>
                        </div>
                        
                        <div>
                          <label className="block text-sm font-medium text-gray-700 mb-2">
                            Location
                          </label>
                          <input
                            type="text"
                            value={form.location}
                            onChange={(e) => setForm(prev => ({ ...prev, location: e.target.value }))}
                            className="w-full px-3 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-blue-500"
                            placeholder="e.g., Nairobi Warehouse"
                          />
                        </div>
                      </div>
                      
                      <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                        <div>
                          <label className="block text-sm font-medium text-gray-700 mb-2">
                            Purchase Date
                          </label>
                          <input
                            type="date"
                            value={form.purchaseDate}
                            onChange={(e) => setForm(prev => ({ ...prev, purchaseDate: e.target.value }))}
                            className="w-full px-3 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-blue-500"
                          />
                        </div>
                        
                        <div>
                          <label className="block text-sm font-medium text-gray-700 mb-2">
                            Warranty Until
                          </label>
                          <input
                            type="date"
                            value={form.warranty}
                            onChange={(e) => setForm(prev => ({ ...prev, warranty: e.target.value }))}
                            className="w-full px-3 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-blue-500"
                          />
                        </div>
                      </div>
                    </div>
                  )}

                  {/* Assignment Tab */}
                  {activeTab === 'assignment' && (
                    <div className="space-y-6">
                      <div>
                        <label className="block text-sm font-medium text-gray-700 mb-2">
                          Assigned To
                        </label>
                        <input
                          type="text"
                          value={form.assignedTo}
                          onChange={(e) => setForm(prev => ({ ...prev, assignedTo: e.target.value }))}
                          className="w-full px-3 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-blue-500"
                          placeholder="Staff name or ID"
                        />
                      </div>
                      
                      <div>
                        <label className="block text-sm font-medium text-gray-700 mb-2">
                          Activity / Project
                        </label>
                        <input
                          type="text"
                          value={form.assignedActivity}
                          onChange={(e) => setForm(prev => ({ ...prev, assignedActivity: e.target.value }))}
                          className="w-full px-3 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-blue-500"
                          placeholder="e.g., Household Survey, Population Census"
                        />
                      </div>
                      
                      <div>
                        <label className="block text-sm font-medium text-gray-700 mb-2">
                          Department
                        </label>
                        <select
                          value={form.department}
                          onChange={(e) => setForm(prev => ({ ...prev, department: e.target.value }))}
                          className="w-full px-3 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-blue-500"
                        >
                          <option value="IT">IT Department</option>
                          <option value="Field Operations">Field Operations</option>
                          <option value="Research">Research</option>
                          <option value="Administration">Administration</option>
                          <option value="Finance">Finance</option>
                          <option value="Logistics">Logistics</option>
                        </select>
                      </div>
                      
                      <div className="bg-blue-50 border border-blue-200 rounded-lg p-4">
                        <div className="flex items-start">
                          <Info className="w-5 h-5 text-blue-500 mr-3 mt-0.5" />
                          <div>
                            <div className="font-medium text-gray-900 mb-1">Assignment Note</div>
                            <p className="text-sm text-gray-600">
                              Assigning a tablet to a staff member will automatically update its status to "Issued".
                              Leave these fields empty if the tablet is not currently assigned.
                            </p>
                          </div>
                        </div>
                      </div>
                    </div>
                  )}

                  {/* Additional Tab */}
                  {activeTab === 'additional' && (
                    <div className="space-y-6">
                      <div>
                        <label className="block text-sm font-medium text-gray-700 mb-2">
                          Notes
                        </label>
                        <textarea
                          value={form.notes}
                          onChange={(e) => setForm(prev => ({ ...prev, notes: e.target.value }))}
                          rows={4}
                          className="w-full px-3 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-blue-500"
                          placeholder="Additional notes, special instructions, or observations..."
                        />
                      </div>
                      
                      <div>
                        <label className="block text-sm font-medium text-gray-700 mb-2">
                          Upload Images
                        </label>
                        <div className="border-2 border-dashed border-gray-300 rounded-lg p-6 text-center">
                          <Upload className="w-12 h-12 text-gray-400 mx-auto mb-3" />
                          <p className="text-gray-600 mb-2">Drag & drop images here or click to browse</p>
                          <p className="text-sm text-gray-500">Supports JPG, PNG up to 5MB each</p>
                          <button
                            type="button"
                            className="mt-4 px-4 py-2 border border-gray-300 rounded-lg hover:bg-gray-50"
                          >
                            Browse Files
                          </button>
                        </div>
                      </div>
                      
                      <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                        <label className="flex items-center space-x-3 p-3 border border-gray-200 rounded-lg hover:bg-gray-50 cursor-pointer">
                          <input type="checkbox" className="h-4 w-4 text-blue-600 rounded border-gray-300 focus:ring-blue-500" />
                          <div>
                            <div className="font-medium text-gray-900">Require Verification</div>
                            <div className="text-sm text-gray-500">Manager approval needed</div>
                          </div>
                        </label>
                        
                        <label className="flex items-center space-x-3 p-3 border border-gray-200 rounded-lg hover:bg-gray-50 cursor-pointer">
                          <input type="checkbox" className="h-4 w-4 text-blue-600 rounded border-gray-300 focus:ring-blue-500" />
                          <div>
                            <div className="font-medium text-gray-900">Send Notification</div>
                            <div className="text-sm text-gray-500">Notify relevant teams</div>
                          </div>
                        </label>
                      </div>
                    </div>
                  )}
                </div>
              </div>
            </form>
          </div>

          {/* Right Column - Preview & Actions */}
          <div className="space-y-6">
            {/* Tablet Preview */}
            <div className="bg-white rounded-xl border border-gray-200 p-6">
              <h2 className="text-lg font-bold text-gray-900 mb-4">Tablet Preview</h2>
              
              <div className="space-y-4">
                <div className="flex items-center justify-between">
                  <div className="flex items-center">
                    <Tablet className="w-5 h-5 text-gray-400 mr-2" />
                    <div>
                      <div className="font-medium text-gray-900">{form.deviceId || "New Tablet"}</div>
                      <div className="text-sm text-gray-600">{form.model || "No model selected"}</div>
                    </div>
                  </div>
                  <span className={`px-2 py-1 rounded text-xs font-medium ${
                    form.status === 'available' ? 'bg-green-100 text-green-800' :
                    form.status === 'issued' ? 'bg-blue-100 text-blue-800' :
                    form.status === 'damaged' ? 'bg-red-100 text-red-800' :
                    form.status === 'missing' ? 'bg-orange-100 text-orange-800' :
                    'bg-yellow-100 text-yellow-800'
                  }`}>
                    {statusOptions.find(s => s.value === form.status)?.label || form.status}
                  </span>
                </div>
                
                <div className="space-y-3">
                  <div className="flex items-center justify-between">
                    <span className="text-sm text-gray-600">Battery:</span>
                    <div className="flex items-center">
                      <Battery className="w-4 h-4 mr-2" />
                      <span className="font-medium">{form.battery}%</span>
                    </div>
                  </div>
                  
                  <div className="flex items-center justify-between">
                    <span className="text-sm text-gray-600">Storage:</span>
                    <div className="flex items-center">
                      <HardDrive className="w-4 h-4 mr-2" />
                      <span className="font-medium">{form.storage}</span>
                    </div>
                  </div>
                  
                  <div className="flex items-center justify-between">
                    <span className="text-sm text-gray-600">RAM:</span>
                    <div className="flex items-center">
                      <MemoryStick className="w-4 h-4 mr-2" />
                      <span className="font-medium">{form.ram}</span>
                    </div>
                  </div>
                  
                  <div className="flex items-center justify-between">
                    <span className="text-sm text-gray-600">OS:</span>
                    <div className="flex items-center">
                      <Cpu className="w-4 h-4 mr-2" />
                      <span className="font-medium">{form.os}</span>
                    </div>
                  </div>
                  
                  <div className="flex items-center justify-between">
                    <span className="text-sm text-gray-600">Location:</span>
                    <div className="flex items-center">
                      <MapPin className="w-4 h-4 mr-2" />
                      <span className="font-medium">{form.location}</span>
                    </div>
                  </div>
                </div>
                
                <div className="pt-4 border-t border-gray-200">
                  <div className="text-sm font-medium text-gray-900 mb-2">Quick Actions</div>
                  <div className="grid grid-cols-2 gap-2">
                    <button
                      type="button"
                      onClick={generateDeviceId}
                      className="p-2 border border-gray-200 rounded text-xs hover:bg-gray-50"
                    >
                      Generate ID
                    </button>
                    <button
                      type="button"
                      onClick={() => setForm(prev => ({ 
                        ...prev, 
                        purchaseDate: new Date().toISOString().split('T')[0],
                        warranty: new Date(new Date().setFullYear(new Date().getFullYear() + 2)).toISOString().split('T')[0]
                      }))}
                      className="p-2 border border-gray-200 rounded text-xs hover:bg-gray-50"
                    >
                      Set Dates
                    </button>
                  </div>
                </div>
              </div>
            </div>

            {/* Validation Status */}
            <div className="bg-white rounded-xl border border-gray-200 p-6">
              <h3 className="font-medium text-gray-900 mb-4 flex items-center">
                <CheckCircle className="w-5 h-5 mr-2" />
                Validation Status
              </h3>
              
              <div className="space-y-3">
                {[
                  { label: 'Device ID', valid: !!form.deviceId.trim() },
                  { label: 'Serial Number', valid: !!form.serialNumber.trim() },
                  { label: 'IMEI', valid: !!form.imei.trim() && form.imei.length === 15 },
                  { label: 'Model', valid: !!form.model },
                  { label: 'Battery Level', valid: form.battery >= 0 && form.battery <= 100 },
                  { label: 'Purchase Date', valid: !!form.purchaseDate },
                ].map((item, index) => (
                  <div key={index} className="flex items-center justify-between">
                    <span className="text-sm text-gray-700">{item.label}</span>
                    {item.valid ? (
                      <CheckCircle className="w-4 h-4 text-green-500" />
                    ) : (
                      <AlertCircle className="w-4 h-4 text-red-500" />
                    )}
                  </div>
                ))}
              </div>
              
              <div className="mt-4 pt-4 border-t border-gray-200">
                <div className="text-sm text-gray-600">
                  {Object.keys(errors).length === 0 
                    ? 'All required fields are valid'
                    : `${Object.keys(errors).length} validation error(s) found`
                  }
                </div>
              </div>
            </div>

            {/* Quick Save Options */}
            <div className="bg-gradient-to-r from-blue-50 to-indigo-50 border border-blue-200 rounded-xl p-6">
              <h3 className="font-medium text-gray-900 mb-4">Quick Save Options</h3>
              
              <div className="space-y-3">
                <button
                  type="submit"
                  form="new-tablet-form"
                  disabled={isSubmitting}
                  className="w-full py-3 bg-blue-600 hover:bg-blue-700 text-white font-medium rounded-lg flex items-center justify-center disabled:opacity-50"
                >
                  {isSubmitting ? (
                    <>
                      <RefreshCw className="w-5 h-5 mr-2 animate-spin" />
                      Saving...
                    </>
                  ) : (
                    <>
                      <Save className="w-5 h-5 mr-2" />
                      Save & Continue
                    </>
                  )}
                </button>
                
                <button
                  type="button"
                  onClick={() => {
                    // Save as draft
                    localStorage.setItem('tabletDraft', JSON.stringify(form));
                    alert('Saved as draft!');
                  }}
                  className="w-full py-3 border border-gray-300 text-gray-700 font-medium rounded-lg hover:bg-gray-50 flex items-center justify-center"
                >
                  <Clipboard className="w-5 h-5 mr-2" />
                  Save as Draft
                </button>
                
                <button
                  type="button"
                  onClick={() => {
                    setForm({
                      deviceId: "",
                      serialNumber: "",
                      imei: "",
                      model: "",
                      status: "available",
                      condition: "good",
                      battery: 100,
                      storage: "128GB",
                      ram: "4GB",
                      os: "Android 13",
                      location: "Nairobi Warehouse",
                      purchaseDate: new Date().toISOString().split('T')[0],
                      warranty: new Date(new Date().setFullYear(new Date().getFullYear() + 2)).toISOString().split('T')[0],
                      assignedTo: "",
                      assignedActivity: "",
                      department: "IT",
                      notes: "",
                    });
                    setErrors({});
                  }}
                  className="w-full py-3 border border-gray-300 text-gray-700 font-medium rounded-lg hover:bg-gray-50 flex items-center justify-center"
                >
                  <X className="w-5 h-5 mr-2" />
                  Clear Form
                </button>
              </div>
            </div>
          </div>
        </div>

        {/* Scanner Modal */}
        {showScanner && (
          <div className="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center z-50 p-4">
            <div className="bg-white rounded-xl w-full max-w-md">
              <div className="p-6 border-b border-gray-200 flex items-center justify-between">
                <h3 className="text-lg font-bold text-gray-900">Scanning...</h3>
                <button
                  onClick={() => setShowScanner(false)}
                  className="p-2 hover:bg-gray-100 rounded-lg"
                >
                  <X className="w-5 h-5" />
                </button>
              </div>
              
              <div className="p-12 text-center">
                <div className="relative">
                  <div className="w-64 h-1 bg-blue-500 animate-pulse rounded-full"></div>
                  <div className="w-64 h-64 border-2 border-blue-400 rounded-lg mt-4 relative overflow-hidden mx-auto">
                    <div className="absolute top-0 left-0 right-0 h-1 bg-blue-500 animate-scan"></div>
                  </div>
                </div>
                <p className="text-gray-600 mt-6">Align barcode within the frame</p>
              </div>
            </div>
          </div>
        )}
      </div>
    </Layout>
  );
}

"use client";

import { useState, useRef, useEffect } from "react";
import {
  QrCode, Barcode, Camera, ChevronLeft, RefreshCw,
  Search, CheckCircle, XCircle, AlertCircle,
  Download, History, Scan, StopCircle, Maximize2, Minimize2,
  CameraOff, ScanLine, ScanFace, ScanText, Zap, ChevronDown, ChevronUp, ChevronRight,
  Tablet
} from "lucide-react";
import Link from "next/link";
import { useRouter } from "next/navigation";
import Layout from "@/components/Layout";
import { ScanResult } from "@/types/tablets";
import Scanner from "@/components/Scanner";

export default function ScanPage() {
  const router = useRouter();
  const [isScanning, setIsScanning] = useState(false);
  const [scanMode, setScanMode] = useState<'barcode' | 'qr'>('barcode');
  const [scanResults, setScanResults] = useState<ScanResult[]>([]);
  const [manualInput, setManualInput] = useState("");
  const [scannerSettings, setScannerSettings] = useState({
    audioFeedback: true,
    vibration: true,
    zoom: 1,
  });
  const [showHistory, setShowHistory] = useState(false);
  const [fullscreen, setFullscreen] = useState(false);
  const [availableCameras, setAvailableCameras] = useState<MediaDeviceInfo[]>([]);
  const [currentTime, setCurrentTime] = useState<string>("");

  const manualInputRef = useRef<HTMLInputElement>(null);

  // Initialize time and cameras
  useEffect(() => {
    // Set current time on client only
    const updateTime = () => {
      setCurrentTime(new Date().toLocaleTimeString([], {
        hour: '2-digit',
        minute: '2-digit',
        hour12: true
      }));
    };

    updateTime();
    const interval = setInterval(updateTime, 1000);

    // Check for available cameras
    const getCameras = async () => {
      try {
        if (navigator?.mediaDevices?.enumerateDevices) {
          const devices = await navigator.mediaDevices.enumerateDevices();
          const videoInput = devices.filter(device => device.kind === 'videoinput');
          setAvailableCameras(videoInput);
        }
      } catch (err) {
        console.error("Error enumerating cameras:", err);
      }
    };
    getCameras();

    return () => {
      clearInterval(interval);
    };
  }, []);

  // Initialize scanning on mount (optional, matches other page?)
  // Actually the other page starts scanning on mount. Let's do that for consistency unless manual start is preferred.
  // The previous implementation had manual start/stop button but defaulted to false? 
  // Let's default to false to let user choose, but maybe auto-start is better for UX.
  // I'll keep it false initially to match previous logic but give clear UI to start.
  // Wait, the other page (issuance) starts automatically. Uniformity suggests auto-start.
  useEffect(() => {
    setIsScanning(true);
  }, []);

  // Focus manual input when camera is off
  useEffect(() => {
    if (!isScanning && manualInputRef.current) {
      manualInputRef.current.focus();
    }
  }, [isScanning]);

  const onScanSuccess = (decodedText: string) => {
    // Play sound if enabled
    if (scannerSettings.audioFeedback) {
      const audio = new Audio('/audio/beep.mp3');
      audio.play().catch(e => console.log("Audio play failed", e));
    }

    // Vibrate if enabled
    if (scannerSettings.vibration && navigator.vibrate) {
      navigator.vibrate(200);
    }

    // Process result
    const isTabletId = decodedText.includes('TAB') || decodedText.includes('KNBS');

    const result: ScanResult = {
      type: scanMode,
      value: decodedText,
      timestamp: new Date().toISOString(),
      deviceId: isTabletId ? decodedText : undefined,
      status: isTabletId ? 'success' : 'error',
      message: isTabletId
        ? `Valid Tablet ID detected: ${decodedText}`
        : `Scanned code: ${decodedText} (Not a recognized Tablet ID format)`
    };

    setScanResults(prev => [result, ...prev]);

    // Pause scanning briefly to avoid duplicates
    setIsScanning(false);
    setTimeout(() => {
      setIsScanning(true);
    }, 1500);
  };

  const handleManualSubmit = () => {
    if (manualInput.trim()) {
      // Simulate a scan result
      const isTabletId = manualInput.includes('TAB') || manualInput.includes('KNBS');

      const result: ScanResult = {
        type: 'barcode', // weak assumption
        value: manualInput,
        timestamp: new Date().toISOString(),
        deviceId: manualInput,
        status: isTabletId ? 'success' : 'error',
        message: isTabletId
          ? `Manually entered: ${manualInput}`
          : `Entry ${manualInput} may not be a valid ID`
      };

      setScanResults(prev => [result, ...prev]);
      setManualInput("");
    }
  };

  const handleClearHistory = () => {
    setScanResults([]);
  };

  const handleExportScans = () => {
    const data = scanResults.map(r => ({
      timestamp: r.timestamp,
      type: r.type,
      deviceId: r.deviceId,
      status: r.status,
      message: r.message
    }));

    const blob = new Blob([JSON.stringify(data, null, 2)], { type: 'application/json' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = `scan-results-${new Date().toISOString().split('T')[0]}.json`;
    a.click();
  };

  const stats = {
    totalScans: scanResults.length,
    successful: scanResults.filter(r => r.status === 'success').length,
    errors: scanResults.filter(r => r.status === 'error').length,
    duplicates: scanResults.filter((r, i, arr) =>
      arr.findIndex(a => a.value === r.value) !== i
    ).length,
  };

  // Format time for history - client-side only
  const formatTime = (isoString: string) => {
    if (typeof window === 'undefined') return '';
    return new Date(isoString).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' });
  };

  return (
    <Layout>
      <div className="min-h-screen bg-gradient-to-br from-gray-900 via-gray-800 to-black text-white">
        {/* Header */}
        <div className="p-4 md:p-6">
          <div className="flex flex-col md:flex-row md:items-center justify-between gap-4 mb-6">
            <div>
              <Link
                href="/tablets"
                className="inline-flex items-center gap-2 text-gray-300 hover:text-white group mb-3"
              >
                <ChevronLeft className="w-5 h-5 group-hover:-translate-x-1 transition-transform" />
                Back to Inventory
              </Link>
              <div className="flex items-center gap-3">
                <div className="p-2.5 bg-gradient-to-r from-purple-500/20 to-blue-500/20 rounded-xl">
                  {scanMode === 'barcode' ? <Barcode className="w-6 h-6" /> : <QrCode className="w-6 h-6" />}
                </div>
                <h1 className="text-3xl font-bold">Tablet Scanner</h1>
              </div>
            </div>

            <div className="flex items-center gap-3">
              <div className="flex items-center gap-2 bg-white/10 rounded-lg px-3 py-2">
                <div className={`w-2 h-2 rounded-full ${isScanning ? 'bg-green-500 animate-pulse' : 'bg-gray-500'}`}></div>
                <span className="text-sm">
                  {isScanning ? 'Scanning...' : 'Scanner Paused'}
                </span>
              </div>

              <div className="flex gap-2">
                <button
                  onClick={() => setIsScanning(!isScanning)}
                  className="p-2.5 bg-white/10 rounded-lg hover:bg-white/20 transition-colors"
                  title={isScanning ? 'Pause Scanner' : 'Resume Scanner'}
                >
                  {isScanning ? <CameraOff className="w-5 h-5" /> : <Camera className="w-5 h-5" />}
                </button>
                <button
                  onClick={() => router.refresh()}
                  className="p-2.5 bg-white/10 rounded-lg hover:bg-white/20 transition-colors"
                  title="Refresh Page"
                >
                  <RefreshCw className="w-5 h-5" />
                </button>
              </div>
            </div>
          </div>

          {/* Mode Selector */}
          <div className="flex flex-wrap gap-2 mb-8">
            <button
              onClick={() => setScanMode('barcode')}
              className={`px-4 py-2.5 rounded-lg font-medium transition-all flex items-center gap-2 ${scanMode === 'barcode'
                ? 'bg-gradient-to-r from-blue-500 to-indigo-600 shadow-lg'
                : 'bg-white/10 hover:bg-white/20'
                }`}
            >
              <Barcode className="w-4 h-4" />
              Barcode Mode
            </button>
            <button
              onClick={() => setScanMode('qr')}
              className={`px-4 py-2.5 rounded-lg font-medium transition-all flex items-center gap-2 ${scanMode === 'qr'
                ? 'bg-gradient-to-r from-blue-500 to-indigo-600 shadow-lg'
                : 'bg-white/10 hover:bg-white/20'
                }`}
            >
              <QrCode className="w-4 h-4" />
              QR Code Mode
            </button>
          </div>

          {/* Scanner Status */}
          <div className="text-center mb-6">
            <p className="text-gray-300 text-lg">
              Scan {scanMode === 'barcode' ? 'barcodes' : 'QR codes'} to verify tablet inventory
            </p>
            <p className="text-sm text-gray-400 mt-2">
              Ensure proper lighting and hold code steady
            </p>
          </div>
        </div>

        {/* Main Scanner Area */}
        <div className="max-w-6xl mx-auto px-4 pb-8">
          <div className="grid lg:grid-cols-3 gap-8">
            {/* Scanner Column (2/3 width) */}
            <div className="lg:col-span-2">
              <div className={`bg-gradient-to-br from-gray-800/50 to-gray-900/50 backdrop-blur-sm rounded-2xl p-4 md:p-6 border border-gray-700/50 ${fullscreen ? 'fixed inset-0 z-50 m-0 rounded-none h-screen bg-black' : ''}`}>

                {/* Fullscreen Controls */}
                {fullscreen && (
                  <div className="absolute top-4 right-4 z-50">
                    <button
                      onClick={() => setFullscreen(false)}
                      className="p-2 bg-black/50 text-white rounded-lg backdrop-blur-sm"
                    >
                      <Minimize2 className="w-6 h-6" />
                    </button>
                  </div>
                )}

                <div className="relative rounded-xl overflow-hidden min-h-[400px]">
                  {!fullscreen && (
                    <div className="absolute top-2 right-2 z-10">
                      <button
                        onClick={() => setFullscreen(true)}
                        className="p-2 bg-black/30 text-white hover:bg-black/50 rounded-lg backdrop-blur-sm transition-colors"
                        title="Fullscreen"
                      >
                        <Maximize2 className="w-5 h-5" />
                      </button>
                    </div>
                  )}

                  <Scanner
                    isScanning={isScanning}
                    setIsScanning={setIsScanning}
                    onScanSuccess={onScanSuccess}
                    scanMode={scanMode}
                    className="h-full min-h-[400px]"
                  />

                  {/* Stats Overlay (on top of scanner) */}
                  <div className="absolute top-4 left-4 flex gap-4 pointer-events-none">
                    <div className="bg-black/40 backdrop-blur-md px-3 py-1.5 rounded-lg border border-white/10">
                      <div className="text-xs text-gray-400 uppercase tracking-wider">Total</div>
                      <div className="text-lg font-bold">{stats.totalScans}</div>
                    </div>
                    <div className="bg-black/40 backdrop-blur-md px-3 py-1.5 rounded-lg border border-white/10">
                      <div className="text-xs text-green-400 uppercase tracking-wider">Success</div>
                      <div className="text-lg font-bold text-green-400">{stats.successful}</div>
                    </div>
                  </div>
                </div>

                {/* Manual Input Fallback */}
                <div className={`mt-8 bg-gray-800/30 backdrop-blur-sm rounded-xl p-6 ${fullscreen ? 'hidden' : ''}`}>
                  <h3 className="text-lg font-medium mb-4 flex items-center gap-2">
                    <Search className="w-5 h-5" />
                    Manual Entry
                  </h3>
                  <div className="flex gap-2">
                    <input
                      ref={manualInputRef}
                      type="text"
                      value={manualInput}
                      onChange={(e) => setManualInput(e.target.value)}
                      placeholder="Enter device ID manually"
                      className="flex-1 bg-gray-700 border border-gray-600 rounded-lg px-4 py-3 text-white placeholder-gray-400 focus:outline-none focus:ring-2 focus:ring-blue-500 focus:border-transparent"
                      onKeyDown={(e) => e.key === 'Enter' && handleManualSubmit()}
                    />
                    <button
                      onClick={handleManualSubmit}
                      disabled={!manualInput.trim()}
                      className="px-6 py-3 bg-gradient-to-r from-blue-600 to-indigo-600 hover:from-blue-700 hover:to-indigo-700 disabled:from-gray-700 disabled:to-gray-700 disabled:cursor-not-allowed rounded-lg font-medium"
                    >
                      Submit
                    </button>
                  </div>
                </div>

                {/* Scan History List (Preview) */}
                {scanResults.length > 0 && !fullscreen && (
                  <div className="mt-6 bg-gray-800/30 backdrop-blur-sm rounded-xl p-4">
                    <button
                      onClick={() => setShowHistory(!showHistory)}
                      className="w-full flex items-center justify-between text-left"
                    >
                      <div className="flex items-center gap-2">
                        <History className="w-4 h-4" />
                        <span className="font-medium">Recent Scans ({scanResults.length})</span>
                      </div>
                      {showHistory ? <ChevronUp className="w-5 h-5" /> : <ChevronDown className="w-5 h-5" />}
                    </button>

                    {showHistory && (
                      <div className="mt-4 space-y-2 max-h-60 overflow-y-auto">
                        {scanResults.map((result, index) => (
                          <div
                            key={index}
                            className={`flex items-center justify-between p-3 rounded-lg hover:bg-gray-700/50 border ${result.status === 'success' ? 'bg-green-500/10 border-green-500/20' : 'bg-red-500/10 border-red-500/20'}`}
                          >
                            <div className="flex-1 min-w-0">
                              <div className="flex items-center gap-2">
                                {result.status === 'success' ? <CheckCircle className="w-4 h-4 text-green-500" /> : <AlertCircle className="w-4 h-4 text-red-500" />}
                                <div className="font-mono text-sm truncate">{result.value}</div>
                              </div>
                              <div className="text-xs text-gray-400 mt-1 pl-6">
                                {formatTime(result.timestamp)} • {result.message}
                              </div>
                            </div>
                            {result.deviceId && (
                              <Link href={`/tablets/${result.deviceId}`} className="ml-2 text-blue-400 hover:text-blue-300 text-xs">
                                View
                              </Link>
                            )}
                          </div>
                        ))}
                      </div>
                    )}
                  </div>
                )}
              </div>
            </div>

            {/* Sidebar (1/3 width) */}
            <div className="space-y-6">
              {/* Quick Actions */}
              <div className="bg-gradient-to-br from-gray-800/50 to-gray-900/50 backdrop-blur-sm rounded-2xl border border-gray-700/50 p-6">
                <h3 className="text-lg font-bold mb-4">Quick Actions</h3>
                <div className="space-y-3">
                  <button
                    onClick={handleExportScans}
                    disabled={scanResults.length === 0}
                    className="w-full flex items-center gap-3 p-3 bg-blue-500/10 hover:bg-blue-500/20 disabled:opacity-50 disabled:cursor-not-allowed rounded-xl transition-colors group text-left"
                  >
                    <div className="p-2 bg-blue-500/20 rounded-lg group-hover:scale-110 transition-transform">
                      <Download className="w-5 h-5 text-blue-400" />
                    </div>
                    <div className="flex-1">
                      <div className="font-medium text-gray-200">Export Results</div>
                      <div className="text-sm text-gray-400">Download JSON report</div>
                    </div>
                    <ChevronRight className="w-5 h-5 text-gray-500" />
                  </button>

                  <button
                    onClick={handleClearHistory}
                    disabled={scanResults.length === 0}
                    className="w-full flex items-center gap-3 p-3 bg-red-500/10 hover:bg-red-500/20 disabled:opacity-50 disabled:cursor-not-allowed rounded-xl transition-colors group text-left"
                  >
                    <div className="p-2 bg-red-500/20 rounded-lg group-hover:scale-110 transition-transform">
                      <XCircle className="w-5 h-5 text-red-400" />
                    </div>
                    <div className="flex-1">
                      <div className="font-medium text-gray-200">Clear History</div>
                      <div className="text-sm text-gray-400">Remove all scans</div>
                    </div>
                  </button>
                </div>
              </div>

              {/* Scanning Tips */}
              <div className="bg-gradient-to-br from-gray-800/50 to-gray-900/50 backdrop-blur-sm rounded-2xl border border-gray-700/50 p-6">
                <h3 className="text-lg font-bold mb-4">Scanning Tips</h3>
                <div className="space-y-3 text-sm text-gray-300">
                  <div className="flex items-start gap-3">
                    <div className="p-1.5 bg-blue-500/20 rounded-lg mt-0.5">
                      <ScanLine className="w-4 h-4" />
                    </div>
                    <div>Hold the scanner steady while focusing</div>
                  </div>
                  <div className="flex items-start gap-3">
                    <div className="p-1.5 bg-blue-500/20 rounded-lg mt-0.5">
                      <ScanFace className="w-4 h-4" />
                    </div>
                    <div>Keep the code fully within the frame</div>
                  </div>
                  <div className="flex items-start gap-3">
                    <div className="p-1.5 bg-blue-500/20 rounded-lg mt-0.5">
                      <ScanText className="w-4 h-4" />
                    </div>
                    <div>Use manual entry if code is damaged</div>
                  </div>
                </div>
              </div>

              {/* System Status */}
              <div className="bg-gradient-to-br from-blue-900/20 to-indigo-900/20 backdrop-blur-sm rounded-2xl border border-blue-700/30 p-6">
                <div className="flex items-center justify-between mb-4">
                  <h3 className="text-lg font-bold">Scanner Status</h3>
                  <div className="flex items-center gap-2">
                    <div className={`w-2 h-2 rounded-full ${isScanning ? 'bg-green-500 animate-pulse' : 'bg-gray-500'}`}></div>
                    <span className="text-sm">{isScanning ? 'Active' : 'Standby'}</span>
                  </div>
                </div>
                <div className="space-y-3 text-sm">
                  <div className="flex justify-between">
                    <span className="text-gray-400">Mode</span>
                    <span className="font-medium capitalize">{scanMode}</span>
                  </div>
                  <div className="flex justify-between">
                    <span className="text-gray-400">Camera</span>
                    <span className="font-medium">{availableCameras.length} available</span>
                  </div>
                  <div className="flex justify-between">
                    <span className="text-gray-400">Session Scans</span>
                    <span className="font-medium">{scanResults.length}</span>
                  </div>
                </div>
              </div>
            </div>
          </div>
        </div>

        {/* Bottom Bar */}
        <div className="mt-8 pt-6 border-t border-gray-700/50">
          <div className="max-w-6xl mx-auto px-4">
            <div className="flex flex-col md:flex-row items-center justify-between gap-4 text-sm text-gray-400">
              <div className="flex items-center gap-6">
                <span className="flex items-center gap-2">
                  <div className="w-2 h-2 bg-emerald-400 rounded-full animate-pulse"></div>
                  Scanner ready
                </span>
                <span>Current time: {currentTime || "Loading..."}</span>
              </div>
              <div className="flex items-center gap-4">
                <button onClick={() => window.print()} className="hover:text-gray-300">Print</button>
                <button onClick={() => window.open('/help/scanner', '_blank')} className="hover:text-gray-300">Help</button>
              </div>
            </div>
          </div>
        </div>
      </div>
    </Layout>
  );
}

"use client";

import { useState, useRef, useEffect } from "react";
import { Camera, CameraOff, AlertCircle, Loader2, RotateCcw } from "lucide-react";
import { Html5Qrcode } from "html5-qrcode";

export type ScannerMode = 'scanning' | 'success' | 'error' | 'loading' | 'camera_off' | 'permission_denied';

interface ScannerProps {
    onScanSuccess: (decodedText: string) => void;
    onScanFailure?: (error: any) => void;
    isScanning: boolean;
    setIsScanning: (scanning: boolean) => void;
    scanMode?: 'qr' | 'barcode';
    containerId?: string;
    className?: string;
    showOverlay?: boolean;
}

export default function Scanner({
    onScanSuccess,
    onScanFailure,
    isScanning,
    setIsScanning,
    scanMode = 'qr',
    containerId = "scanner-container",
    className = "",
    showOverlay = true
}: ScannerProps) {
    const [scannerStatus, setScannerStatus] = useState<ScannerMode>('loading');
    const [cameraError, setCameraError] = useState<string | null>(null);
    const [availableCameras, setAvailableCameras] = useState<Array<{ id: string, label: string }>>([]);
    const [selectedCamera, setSelectedCamera] = useState<string>('');

    const scannerRef = useRef<Html5Qrcode | null>(null);
    const scannerContainerRef = useRef<HTMLDivElement>(null);

    // Initialize camera list
    useEffect(() => {
        const getCameras = async () => {
            try {
                if (!navigator.mediaDevices || !navigator.mediaDevices.enumerateDevices) {
                    throw new Error("Camera API not supported");
                }
                const devices = await navigator.mediaDevices.enumerateDevices();
                const videoDevices = devices.filter(device => device.kind === 'videoinput');

                if (videoDevices.length > 0) {
                    setAvailableCameras(videoDevices.map(d => ({
                        id: d.deviceId,
                        label: d.label || `Camera ${d.deviceId.slice(0, 5)}...`
                    })));
                    // Prefer back camera if available (usually last in list on mobile, but environment facing mode handles usually)
                    setSelectedCamera(videoDevices[0].deviceId);
                } else {
                    setCameraError("No camera found");
                    setScannerStatus('error');
                }
            } catch (err: any) {
                console.error("Error getting cameras:", err);
                setCameraError(err.message || "Failed to access camera");
                setScannerStatus('permission_denied');
            }
        };

        getCameras();

        return () => {
            stopScannerInstance();
        };
    }, []);

    // Handle scanning state changes
    useEffect(() => {
        if (isScanning) {
            startScannerInstance();
        } else {
            stopScannerInstance();
            setScannerStatus('camera_off');
        }
        // eslint-disable-next-line react-hooks/exhaustive-deps
    }, [isScanning, selectedCamera]);

    const startScannerInstance = async () => {
        try {
            setCameraError(null);
            setScannerStatus('loading');

            // Stop existing instance if any
            await stopScannerInstance();

            if (!document.getElementById(containerId)) {
                console.warn(`Scanner container ${containerId} not found`);
                return;
            }

            const config = {
                fps: 10,
                qrbox: { width: 250, height: 250 },
                aspectRatio: 1.0,
            };

            scannerRef.current = new Html5Qrcode(containerId);

            const cameraId = selectedCamera || (availableCameras[0]?.id);

            const successCallback = (decodedText: string, result: any) => {
                onScanSuccess(decodedText);
                // Don't stop automatically here, let parent decide via prop update
            };

            const errorCallback = (errorMessage: string) => {
                if (onScanFailure) onScanFailure(errorMessage);
            };

            if (!cameraId) {
                await scannerRef.current.start(
                    { facingMode: "environment" },
                    config,
                    successCallback,
                    errorCallback
                );
            } else {
                await scannerRef.current.start(
                    cameraId,
                    config,
                    successCallback,
                    errorCallback
                );
            }

            setScannerStatus('scanning');
        } catch (err: any) {
            console.error("Error starting scanner:", err);
            let errorMsg = "Failed to start camera";
            let status: ScannerMode = 'error';

            if (err.name === 'NotAllowedError') {
                errorMsg = "Camera access denied";
                status = 'permission_denied';
            } else if (err.name === 'NotFoundError') {
                errorMsg = "No camera found";
            } else if (err.name === 'NotReadableError') {
                errorMsg = "Camera in use by another app";
            }

            setCameraError(errorMsg);
            setScannerStatus(status);
            setIsScanning(false); // Propagate stop to parent
        }
    };

    const stopScannerInstance = async () => {
        try {
            if (scannerRef.current && scannerRef.current.isScanning) {
                await scannerRef.current.stop();
                scannerRef.current.clear();
            }
        } catch (err) {
            console.error("Error stopping scanner:", err);
        }
    };

    const switchCamera = () => {
        if (availableCameras.length <= 1) return;

        const currentIndex = availableCameras.findIndex(c => c.id === selectedCamera);
        const nextIndex = (currentIndex + 1) % availableCameras.length;
        setSelectedCamera(availableCameras[nextIndex].id);
        // Effect will trigger restart
    };

    return (
        <div className={`relative rounded-xl overflow-hidden bg-black min-h-[300px] ${className}`}>
            {/* HTML5-QRCode Scanner Element */}
            <div id={containerId} className="w-full h-full" style={{ display: scannerStatus === 'scanning' ? 'block' : 'none' }}></div>

            {/* States Display */}
            {scannerStatus !== 'scanning' && (
                <div className="absolute inset-0 flex flex-col items-center justify-center p-6 text-center text-white bg-gray-900">
                    {scannerStatus === 'loading' && (
                        <>
                            <Loader2 className="w-12 h-12 text-knbs-500 animate-spin mb-4" />
                            <p>Initializing camera...</p>
                        </>
                    )}
                    {scannerStatus === 'camera_off' && (
                        <>
                        <div className="w-20 h-20 bg-gray-900/50 backdrop-blur-sm rounded-full flex items-center justify-center mb-4 border border-knbs-500/30">\n                                <CameraOff className="w-10 h-10 text-knbs-400" />\n                            </div>
                            <p className="text-gray-400 mb-4">Camera is disabled</p>
                            <button
                                onClick={() => setIsScanning(true)}\n                                className="px-6 py-2 bg-knbs-500 hover:bg-knbs-600 rounded-lg text-white"\n                            >
                                Enable Camera
                            </button>
                        </>
                    )}
                    {(scannerStatus === 'error' || scannerStatus === 'permission_denied') && (
                        <>
                            <AlertCircle className="w-12 h-12 text-red-400 mb-4" />
                            <p className="text-lg font-medium mb-2">Camera Error</p>
                            <p className="text-gray-400 mb-6">{cameraError}</p>
                            <button
                                onClick={() => setIsScanning(true)} // Try restart\n                                className="px-6 py-2 bg-knbs-600/50 hover:bg-knbs-700/50 backdrop-blur-sm rounded-lg text-white flex items-center border border-knbs-400/50"\n                            >
                                <RotateCcw className="w-4 h-4 mr-2" />
                                Try Again
                            </button>
                        </>
                    )}
                </div>
            )}

            {/* Overlay for scanning */}
            {showOverlay && scannerStatus === 'scanning' && (
                <div className="absolute inset-0 pointer-events-none">
                    {/* Scanner Frame */}
                    <div className="absolute top-1/2 left-1/2 transform -translate-x-1/2 -translate-y-1/2 w-64 h-64 border-4 border-knbs-400/70 rounded-xl shadow-2xl">
                        {/* Corners */}
                        <div className="absolute -top-1 -left-1 w-8 h-8 border-t-3 border-l-3 border-knbs-300 bg-knbs-500/20 rounded-tl-lg shadow-lg"></div>\n                        <div className="absolute -top-1 -right-1 w-8 h-8 border-t-3 border-r-3 border-knbs-300 bg-knbs-500/20 rounded-tr-lg shadow-lg"></div>\n                        <div className="absolute -bottom-1 -left-1 w-8 h-8 border-b-3 border-l-3 border-knbs-300 bg-knbs-500/20 rounded-bl-lg shadow-lg"></div>\n                        <div className="absolute -bottom-1 -right-1 w-8 h-8 border-b-3 border-r-3 border-knbs-300 bg-knbs-500/20 rounded-br-lg shadow-lg"></div>

                        {/* Scanning Line */}
                        <div className="absolute top-0 left-0 right-0 h-1 bg-gradient-to-r from-transparent via-knbs-400/90 to-transparent animate-scan shadow-lg"></div>
                    </div>

                    {/* Controls Overlay */}
                    <div className="absolute bottom-4 left-0 right-0 flex justify-center pointer-events-auto">
                        {availableCameras.length > 1 && (
                            <button\n                                onClick={switchCamera}\n                                className="px-4 py-2 bg-knbs-900/60 hover:bg-knbs-800/70 text-white rounded-full text-sm backdrop-blur-sm flex items-center border border-knbs-500/40"\n                            >
                                <Camera className="w-4 h-4 mr-2" />
                                Switch Camera
                            </button>
                        )}
                    </div>
                </div>
            )}
        </div>
    );
}
